import hashlib
import os
import tempfile
import unittest

from offline_coordination import audit, receipt, storage, transaction
from offline_coordination.storage import CorruptStateError
from offline_coordination.transaction import inspect
from offline_coordination.transaction import (
    CorruptTransactionError,
)
from offline_coordination.audit import CorruptAuditError
from offline_coordination.receipt import CorruptReceiptError

STATE = {"clock": {"n1": 0}, "records": {}}
OTHER_STATE = {"clock": {"n1": 7}, "records": {}}
EVENT = {"source": "n1", "kind": "local", "detail": "first"}
OTHER_EVENT = {"source": "n2", "kind": "merge", "detail": "other"}

ITEM_KEYS = ("audit", "id", "stage", "state", "status")


def state_digest(state=STATE) -> str:
    payload = storage._serialize(*storage._validated_state(state))
    return hashlib.sha256(payload).hexdigest()


def planned_audit_digest(audit_path: str, event=EVENT) -> str:
    return transaction._planned_audit_digest(audit._read_all_records(audit_path), event)


class InspectFixture(unittest.TestCase):
    def setUp(self) -> None:
        self.dir = tempfile.mkdtemp()
        self.paths = {
            "checkpoint": os.path.join(self.dir, "checkpoint.json"),
            "state": os.path.join(self.dir, "state.json"),
            "audit": os.path.join(self.dir, "audit.log"),
            "receipt": os.path.join(self.dir, "receipt.json"),
        }
        self.sd = state_digest()
        self.ad = planned_audit_digest(self.paths["audit"])

    def checkpoint(self, rid="x", stage="prepared", sd=None, ad=None) -> None:
        sd = self.sd if sd is None else sd
        ad = self.ad if ad is None else ad
        transaction.checkpoint(
            self.paths["checkpoint"],
            {"id": rid, "state": sd, "audit": ad, "stage": "prepared"},
        )
        current = "prepared"
        for next_stage in ("state", "audit", "committed"):
            if current == stage:
                break
            transaction.checkpoint(
                self.paths["checkpoint"],
                {"id": rid, "state": sd, "audit": ad, "stage": next_stage},
            )
            current = next_stage

    def set_state(self, mode: str) -> None:
        if mode == "match":
            storage.save_state(self.paths["state"], STATE)
        elif mode == "other":
            storage.save_state(self.paths["state"], OTHER_STATE)
        elif mode == "none":
            for suffix in ("", ".bak", ".tmp"):
                try:
                    os.remove(self.paths["state"] + suffix)
                except FileNotFoundError:
                    pass
        else:  # pragma: no cover - test programming error
            raise AssertionError(mode)

    def set_audit(self, mode: str) -> None:
        if mode == "match":
            audit.append(self.paths["audit"], EVENT)
        elif mode == "other":
            audit.append(self.paths["audit"], OTHER_EVENT)
        elif mode == "none":
            try:
                os.remove(self.paths["audit"])
            except FileNotFoundError:
                pass
        else:  # pragma: no cover
            raise AssertionError(mode)

    def set_receipt(self, mode: str) -> None:
        if mode == "match":
            receipt.put(
                self.paths["receipt"],
                {"id": "x", "state": self.sd, "audit": self.ad},
            )
        elif mode == "wrong":
            receipt.put(
                self.paths["receipt"],
                {"id": "x", "state": "f" * 64, "audit": self.ad},
            )
        elif mode == "none":
            try:
                os.remove(self.paths["receipt"])
            except FileNotFoundError:
                pass
        else:  # pragma: no cover
            raise AssertionError(mode)

    def reset(self) -> None:
        for name in os.listdir(self.dir):
            os.remove(os.path.join(self.dir, name))
        self.sd = state_digest()
        self.ad = planned_audit_digest(self.paths["audit"])

    def build(
        self, stage: str, *, state_mode="none", audit_mode="none",
        receipt_mode="none",
    ):
        self.reset()
        self.checkpoint(stage=stage)
        self.set_state(state_mode)
        self.set_audit(audit_mode)
        self.set_receipt(receipt_mode)
        return inspect(self.paths)[0]

    def snapshot(self) -> tuple[dict[str, bytes], list[str]]:
        files = {}
        for name in os.listdir(self.dir):
            with open(os.path.join(self.dir, name), "rb") as handle:
                files[name] = handle.read()
        return files, sorted(os.listdir(self.dir))


class InspectValidationTest(InspectFixture):
    def test_paths_must_be_dict(self) -> None:
        for bad in (None, [], "x", 1, True):
            with self.assertRaises(TypeError, msg=f"paths={bad!r}"):
                inspect(bad)

    def test_paths_key_set_must_match_exactly(self) -> None:
        with self.assertRaises(ValueError):
            inspect({key: self.paths[key] for key in self.paths if key != "receipt"})
        with self.assertRaises(ValueError):
            inspect({**self.paths, "extra": "z"})

    def test_paths_values_must_be_str(self) -> None:
        for key in self.paths:
            with self.assertRaises(TypeError, msg=f"key={key}"):
                inspect({**self.paths, key: 1})

    def test_type_errors_precede_file_access(self) -> None:
        # A corrupt checkpoint must not mask paths type/value errors.
        with open(self.paths["checkpoint"], "wb") as handle:
            handle.write(b"")
        with self.assertRaises(TypeError):
            inspect(None)
        with self.assertRaises(ValueError):
            inspect({key: self.paths[key] for key in self.paths if key != "state"})


class InspectBasicTest(InspectFixture):
    def test_missing_checkpoint_returns_empty_list(self) -> None:
        self.assertEqual(inspect(self.paths), [])

    def test_missing_checkpoint_ignores_other_artifacts(self) -> None:
        # Even an unrecoverable state is not consulted without a checkpoint.
        with open(self.paths["state"], "wb") as handle:
            handle.write(b"garbage")
        with open(self.paths["state"] + ".bak", "wb") as handle:
            handle.write(b"garbage")
        os.mkdir(self.paths["audit"])
        self.assertEqual(inspect(self.paths), [])

    def test_item_key_order_and_checkpoint_values(self) -> None:
        item = self.build("prepared")
        self.assertEqual(tuple(item.keys()), ITEM_KEYS)
        self.assertEqual(item["audit"], self.ad)
        self.assertEqual(item["id"], "x")
        self.assertEqual(item["stage"], "prepared")
        self.assertEqual(item["state"], self.sd)
        self.assertEqual(item["status"], "recoverable")

    def test_items_sorted_by_id_and_fresh_copies(self) -> None:
        self.checkpoint(rid="c", stage="committed")
        self.checkpoint(rid="a", stage="prepared")
        self.checkpoint(rid="b", stage="state")
        result = inspect(self.paths)
        self.assertEqual([item["id"] for item in result], ["a", "b", "c"])
        self.assertTrue(all(tuple(item.keys()) == ITEM_KEYS for item in result))
        again = inspect(self.paths)
        self.assertIsNot(result, again)
        self.assertTrue(all(x is not y for x, y in zip(result, again)))
        result[0]["status"] = "mutated"
        self.assertEqual(inspect(self.paths)[0]["status"], "recoverable")


class InspectStatusMatrixTest(InspectFixture):
    def test_prepared_requires_no_audit_record_and_no_receipt(self) -> None:
        # S is irrelevant at prepared.
        for state_mode in ("none", "match", "other"):
            item = self.build(
                "prepared", state_mode=state_mode,
                audit_mode="none", receipt_mode="none",
            )
            self.assertEqual(item["status"], "recoverable", state_mode)

        self.assertEqual(
            self.build("prepared", audit_mode="match", receipt_mode="none")[
                "status"
            ],
            "conflict",
        )
        self.assertEqual(
            self.build("prepared", audit_mode="other", receipt_mode="none")[
                "status"
            ],
            "recoverable",
        )
        self.assertEqual(
            self.build("prepared", audit_mode="none", receipt_mode="match")[
                "status"
            ],
            "conflict",
        )
        self.assertEqual(
            self.build("prepared", audit_mode="none", receipt_mode="wrong")[
                "status"
            ],
            "conflict",
        )

    def test_state_stage_requires_matching_state_and_no_receipt(self) -> None:
        # A is irrelevant at state.
        for audit_mode in ("none", "match", "other"):
            item = self.build(
                "state", state_mode="match", audit_mode=audit_mode,
                receipt_mode="none",
            )
            self.assertEqual(item["status"], "recoverable", audit_mode)

        self.assertEqual(
            self.build("state", state_mode="other", receipt_mode="none")[
                "status"
            ],
            "conflict",
        )
        self.assertEqual(
            self.build("state", state_mode="none", receipt_mode="none")[
                "status"
            ],
            "conflict",
        )
        self.assertEqual(
            self.build("state", state_mode="match", receipt_mode="match")[
                "status"
            ],
            "conflict",
        )
        self.assertEqual(
            self.build("state", state_mode="match", receipt_mode="wrong")[
                "status"
            ],
            "conflict",
        )

    def test_audit_stage_requires_state_audit_and_absent_or_matching_receipt(
        self,
    ) -> None:
        self.assertEqual(
            self.build(
                "audit", state_mode="match", audit_mode="match",
                receipt_mode="none",
            )["status"],
            "recoverable",
        )
        self.assertEqual(
            self.build(
                "audit", state_mode="match", audit_mode="match",
                receipt_mode="match",
            )["status"],
            "recoverable",
        )
        self.assertEqual(
            self.build(
                "audit", state_mode="other", audit_mode="match",
                receipt_mode="none",
            )["status"],
            "conflict",
        )
        self.assertEqual(
            self.build(
                "audit", state_mode="match", audit_mode="other",
                receipt_mode="none",
            )["status"],
            "conflict",
        )
        self.assertEqual(
            self.build(
                "audit", state_mode="match", audit_mode="none",
                receipt_mode="none",
            )["status"],
            "conflict",
        )
        self.assertEqual(
            self.build(
                "audit", state_mode="match", audit_mode="match",
                receipt_mode="wrong",
            )["status"],
            "conflict",
        )

    def test_committed_requires_everything_bound(self) -> None:
        self.assertEqual(
            self.build(
                "committed", state_mode="match", audit_mode="match",
                receipt_mode="match",
            )["status"],
            "committed",
        )
        self.assertEqual(
            self.build(
                "committed", state_mode="other", audit_mode="match",
                receipt_mode="match",
            )["status"],
            "conflict",
        )
        self.assertEqual(
            self.build(
                "committed", state_mode="match", audit_mode="other",
                receipt_mode="match",
            )["status"],
            "conflict",
        )
        self.assertEqual(
            self.build(
                "committed", state_mode="match", audit_mode="match",
                receipt_mode="none",
            )["status"],
            "conflict",
        )
        self.assertEqual(
            self.build(
                "committed", state_mode="match", audit_mode="match",
                receipt_mode="wrong",
            )["status"],
            "conflict",
        )

    def test_independent_records_classified_separately(self) -> None:
        self.checkpoint(rid="c", stage="committed")
        self.checkpoint(rid="a", stage="prepared")
        self.set_state("match")
        self.set_audit("match")
        receipt.put(
            self.paths["receipt"],
            {"id": "c", "state": self.sd, "audit": self.ad},
        )
        statuses = {item["id"]: item["status"] for item in inspect(self.paths)}
        # 'a' is prepared but its audit record is already present -> conflict;
        # 'c' has state, audit and receipt all bound -> committed.
        self.assertEqual(statuses, {"a": "conflict", "c": "committed"})


class InspectStateFallbackTest(InspectFixture):
    def test_valid_backup_keeps_corrupt_main_loadable_but_s_uses_main(self) -> None:
        # Rotate STATE into the backup, then corrupt the new main.
        storage.save_state(self.paths["state"], STATE)
        storage.save_state(self.paths["state"], OTHER_STATE)
        with open(self.paths["state"], "wb") as handle:
            handle.write(b"not a state")
        self.checkpoint(stage="committed")
        self.set_audit("match")
        self.set_receipt("match")
        # The backup is valid, so no CorruptStateError -- but S is about
        # the main file, so the committed checkpoint is a conflict.
        self.assertEqual(inspect(self.paths)[0]["status"], "conflict")

    def test_missing_main_with_valid_backup_is_not_corrupt(self) -> None:
        storage.save_state(self.paths["state"], STATE)
        storage.save_state(self.paths["state"], STATE)
        os.remove(self.paths["state"])
        self.assertTrue(os.path.exists(self.paths["state"] + ".bak"))
        self.checkpoint(stage="prepared")
        self.assertEqual(inspect(self.paths)[0]["status"], "recoverable")

    def test_tmp_file_alone_is_not_an_existing_state(self) -> None:
        with open(self.paths["state"] + ".tmp", "wb") as handle:
            handle.write(b"garbage")
        self.checkpoint(stage="prepared")
        self.assertEqual(inspect(self.paths)[0]["status"], "recoverable")


class InspectCorruptionTest(InspectFixture):
    def test_corrupt_main_and_backup_raises_corrupt_state_error(self) -> None:
        self.checkpoint(stage="prepared")
        with open(self.paths["state"], "wb") as handle:
            handle.write(b"garbage")
        with open(self.paths["state"] + ".bak", "wb") as handle:
            handle.write(b"also garbage")
        with self.assertRaises(CorruptStateError):
            inspect(self.paths)

    def test_corrupt_main_without_backup_raises_corrupt_state_error(self) -> None:
        self.checkpoint(stage="committed")
        with open(self.paths["state"], "wb") as handle:
            handle.write(b"{")
        with self.assertRaises(CorruptStateError):
            inspect(self.paths)

    def test_corrupt_checkpoint_propagates(self) -> None:
        with open(self.paths["checkpoint"], "wb") as handle:
            handle.write(b"")
        with self.assertRaises(CorruptTransactionError):
            inspect(self.paths)

    def test_corrupt_audit_propagates(self) -> None:
        self.checkpoint(stage="prepared")
        with open(self.paths["audit"], "wb") as handle:
            handle.write(b"not json\n")
        with self.assertRaises(CorruptAuditError):
            inspect(self.paths)

    def test_corrupt_receipt_propagates(self) -> None:
        self.checkpoint(stage="prepared")
        with open(self.paths["receipt"], "wb") as handle:
            handle.write(b"")
        with self.assertRaises(CorruptReceiptError):
            inspect(self.paths)

    def test_os_error_propagates(self) -> None:
        self.checkpoint(stage="prepared")
        os.mkdir(self.paths["audit"])
        with self.assertRaises(OSError):
            inspect(self.paths)

    def test_corrupt_state_os_error_is_not_value_conflict(self) -> None:
        self.checkpoint(stage="committed")
        with open(self.paths["state"], "wb") as handle:
            handle.write(b"garbage")
        try:
            inspect(self.paths)
        except ValueError as exc:
            self.assertIsInstance(exc, CorruptStateError)
        else:  # pragma: no cover
            self.fail("expected CorruptStateError")


class InspectReadOnlyTest(InspectFixture):
    def assert_unchanged(self) -> None:
        before = self.snapshot()
        inspect(self.paths)
        self.assertEqual(self.snapshot(), before)

    def test_read_only_on_recoverable_prepared(self) -> None:
        self.checkpoint(stage="prepared")
        self.assert_unchanged()

    def test_read_only_on_committed(self) -> None:
        self.checkpoint(stage="committed")
        self.set_state("match")
        self.set_audit("match")
        self.set_receipt("match")
        self.assert_unchanged()

    def test_read_only_on_conflict(self) -> None:
        # A committed checkpoint without any of its artifacts is a conflict.
        self.checkpoint(stage="committed")
        self.assert_unchanged()

    def test_read_only_on_corrupt_state(self) -> None:
        self.checkpoint(stage="prepared")
        with open(self.paths["state"], "wb") as handle:
            handle.write(b"garbage")
        before = self.snapshot()
        with self.assertRaises(CorruptStateError):
            inspect(self.paths)
        self.assertEqual(self.snapshot(), before)

    def test_no_tmp_files_created(self) -> None:
        self.checkpoint(stage="committed")
        self.set_state("match")
        self.set_audit("match")
        self.set_receipt("match")
        inspect(self.paths)
        self.assertEqual(
            [name for name in os.listdir(self.dir) if name.endswith(".tmp")],
            [],
        )


def commit_paths(directory: str) -> dict[str, str]:
    return {
        "checkpoint": os.path.join(directory, "checkpoint.json"),
        "state": os.path.join(directory, "state.json"),
        "audit": os.path.join(directory, "audit.log"),
        "receipt": os.path.join(directory, "receipt.json"),
    }


class CommitCorruptStateTest(unittest.TestCase):
    def setUp(self) -> None:
        self.dir = tempfile.mkdtemp()
        self.paths = commit_paths(self.dir)

    def write(self, name: str, payload: bytes) -> None:
        with open(os.path.join(self.dir, name), "wb") as handle:
            handle.write(payload)

    def request(self, state=STATE, event=EVENT, rid="x") -> dict:
        return {"id": rid, "state": state, "event": event}

    def snapshot(self) -> dict[str, bytes]:
        files = {}
        for name in os.listdir(self.dir):
            with open(os.path.join(self.dir, name), "rb") as handle:
                files[name] = handle.read()
        return files

    def test_corrupt_main_and_backup_before_first_commit_raises(self) -> None:
        self.write("state.json", b"garbage")
        self.write("state.json.bak", b"also garbage")
        before = self.snapshot()
        with self.assertRaises(CorruptStateError):
            transaction.commit(self.paths, self.request())
        self.assertEqual(self.snapshot(), before)

    def test_corrupt_main_without_backup_at_committed_raises(self) -> None:
        result = transaction.commit(self.paths, self.request())
        self.assertEqual(result["stage"], "committed")
        self.write("state.json", b"junk")
        with self.assertRaises(CorruptStateError):
            transaction.commit(self.paths, self.request())

    def test_valid_backup_lets_recovery_commit_finish(self) -> None:
        # prepared checkpoint, main corrupt, backup holding the bound state
        storage.save_state(self.paths["state"], STATE)
        sd = state_digest()
        ad = planned_audit_digest(self.paths["audit"])
        transaction.checkpoint(
            self.paths["checkpoint"],
            {"id": "x", "state": sd, "audit": ad, "stage": "prepared"},
        )
        storage.save_state(self.paths["state"], OTHER_STATE)
        self.write("state.json", b"corrupt main")
        result = transaction.commit(self.paths, self.request())
        self.assertEqual(result["stage"], "committed")
        self.assertEqual(inspect(self.paths)[0]["status"], "committed")

    def test_conflicting_valid_state_is_value_error_not_corrupt(self) -> None:
        transaction.commit(self.paths, self.request())
        storage.save_state(self.paths["state"], OTHER_STATE)
        before = self.snapshot()
        with self.assertRaises(ValueError) as caught:
            transaction.commit(self.paths, self.request())
        self.assertNotIsInstance(caught.exception, CorruptStateError)
        self.assertEqual(self.snapshot(), before)

    def test_recoverable_state_stage_resumes_and_is_idempotent(self) -> None:
        storage.save_state(self.paths["state"], STATE)
        sd = state_digest()
        ad = planned_audit_digest(self.paths["audit"])
        for stage in ("prepared", "state"):
            transaction.checkpoint(
                self.paths["checkpoint"],
                {"id": "x", "state": sd, "audit": ad, "stage": stage},
            )
        self.assertEqual(inspect(self.paths)[0]["status"], "recoverable")
        result = transaction.commit(self.paths, self.request())
        self.assertEqual(result["stage"], "committed")
        files_after = self.snapshot()
        replay = transaction.commit(self.paths, self.request())
        self.assertEqual(replay, result)
        self.assertEqual(self.snapshot(), files_after)
        self.assertEqual(inspect(self.paths)[0]["status"], "committed")


if __name__ == "__main__":
    unittest.main()

"""Idempotent receipts binding a state to an audit record.

A receipt only names an ``id`` and the two 64-char lowercase hex digests of
the state and audit record it binds; the state and audit bytes themselves
are never read or written here.  Receipts are kept in an index stored as
UTF-8 compact JSON::

    {"items":[{"audit":...,"id":...,"state":...},...],"version":1}\\n

The top-level keys are fixed in the order ``items`` then ``version`` and
``version`` is always the integer 1.  ``items`` is an array of records
sorted ascending by ``id`` (ids are unique); each record carries the str
keys ``id``, ``state`` and ``audit`` and is canonically encoded with the
key order ``audit``, ``id``, ``state``.  Non-ASCII characters are preserved
unescaped and the file ends with exactly one ``\\n``.

A missing index file stands for an empty index; an existing file that
violates any byte, structure, order or field rule is corrupt.
"""

from __future__ import annotations

import json
import os
import re
from typing import Any

AUDIT = "audit"
ID = "id"
STATE = "state"

ITEMS = "items"
VERSION = "version"

_RECEIPT_KEYS = (ID, STATE, AUDIT)
_RECORD_KEYS = (AUDIT, ID, STATE)
_INDEX_KEYS = (ITEMS, VERSION)
_INDEX_VERSION = 1

_ID_RE = re.compile(r"[A-Za-z0-9._-]{1,64}\Z")
_DIGEST_RE = re.compile(r"[0-9a-f]{64}\Z")


class CorruptReceiptError(ValueError):
    """The receipt index exists but its bytes are not a valid index."""


def _is_digest(value: Any) -> bool:
    return isinstance(value, str) and _DIGEST_RE.fullmatch(value) is not None


def _validated_receipt(receipt: Any) -> dict[str, str]:
    """Validate one receipt and return a fresh dict in record key order."""
    if not isinstance(receipt, dict):
        raise TypeError("receipt must be a dict")
    if set(receipt.keys()) != set(_RECEIPT_KEYS):
        raise ValueError(
            "receipt must contain exactly the keys 'id', 'state' and 'audit'"
        )
    for key in _RECEIPT_KEYS:
        if not isinstance(receipt[key], str):
            raise TypeError(f"receipt {key} must be a str")
    receipt_id = receipt[ID]
    if _ID_RE.fullmatch(receipt_id) is None:
        raise ValueError("receipt id must match [A-Za-z0-9._-]{1,64}")
    if not _is_digest(receipt[STATE]):
        raise ValueError("receipt state must be 64 lowercase hex characters")
    if not _is_digest(receipt[AUDIT]):
        raise ValueError("receipt audit must be 64 lowercase hex characters")
    return {AUDIT: receipt[AUDIT], ID: receipt_id, STATE: receipt[STATE]}


def _serialize_index(records: list[dict[str, str]]) -> bytes:
    ordered = [
        {AUDIT: record[AUDIT], ID: record[ID], STATE: record[STATE]}
        for record in records
    ]
    index = {ITEMS: ordered, VERSION: _INDEX_VERSION}
    text = json.dumps(index, ensure_ascii=False, separators=(",", ":")) + "\n"
    return text.encode("utf-8")


def _parse_index(raw: bytes) -> list[dict[str, str]]:
    """Validate every byte of a receipt index and return its records.

    Raises :class:`CorruptReceiptError` for any UTF-8/JSON failure,
    non-canonical byte encoding, wrong key set or order, bad version,
    duplicate or unsorted ids, or a field that is not a well-formed str.
    """
    if raw == b"":
        raise CorruptReceiptError("receipt index is empty")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptReceiptError("receipt index is not valid UTF-8") from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise CorruptReceiptError("receipt index is not valid JSON") from exc

    if not isinstance(data, dict):
        raise CorruptReceiptError("receipt index must be a JSON object")
    if set(data.keys()) != set(_INDEX_KEYS):
        raise CorruptReceiptError(
            "receipt index must contain exactly the keys 'items' and 'version'"
        )
    if list(data.keys()) != list(_INDEX_KEYS):
        raise CorruptReceiptError(
            "receipt index keys must be in the order 'items', 'version'"
        )
    version = data[VERSION]
    # bool is a subclass of int; the version must be a genuine integer.
    if isinstance(version, bool) or not isinstance(version, int) or version != 1:
        raise CorruptReceiptError("receipt index version must be the integer 1")
    raw_items = data[ITEMS]
    if not isinstance(raw_items, list):
        raise CorruptReceiptError("receipt index items must be an array")

    records: list[dict[str, str]] = []
    for position, item in enumerate(raw_items):
        where = f"receipt index item {position}"
        if not isinstance(item, dict):
            raise CorruptReceiptError(f"{where} must be a JSON object")
        if set(item.keys()) != set(_RECORD_KEYS):
            raise CorruptReceiptError(
                f"{where} must contain exactly the keys 'audit', 'id' and 'state'"
            )
        if list(item.keys()) != list(_RECORD_KEYS):
            raise CorruptReceiptError(
                f"{where} keys must be in the order 'audit', 'id', 'state'"
            )
        audit_digest = item[AUDIT]
        record_id = item[ID]
        state_digest = item[STATE]
        if not isinstance(record_id, str) or _ID_RE.fullmatch(record_id) is None:
            raise CorruptReceiptError(f"{where} has an invalid id")
        if not _is_digest(state_digest):
            raise CorruptReceiptError(
                f"{where} state must be 64 lowercase hex characters"
            )
        if not _is_digest(audit_digest):
            raise CorruptReceiptError(
                f"{where} audit must be 64 lowercase hex characters"
            )
        records.append(
            {AUDIT: audit_digest, ID: record_id, STATE: state_digest}
        )

    ids = [record[ID] for record in records]
    if any(left >= right for left, right in zip(ids, ids[1:])):
        raise CorruptReceiptError(
            "receipt index ids must be unique and sorted ascending"
        )

    # Reject stray whitespace, non-canonical escapes, and any encoding that
    # is not the single compact form of the validated structure.
    if _serialize_index(records) != raw:
        raise CorruptReceiptError("receipt index is not canonically encoded")
    return records


def _read_index(path: str) -> list[dict[str, str]]:
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return []
    return _parse_index(raw)


def _atomic_write(path: str, payload: bytes) -> None:
    tmp_path = path + ".tmp"
    with open(tmp_path, "wb") as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    try:
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise
    fd = os.open(os.path.dirname(os.path.abspath(path)), os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def put(path: str, receipt: dict[str, str]) -> dict[str, str]:
    """Bind ``receipt``'s state and audit digests under its id in the index.

    A new id is added and the index is atomically replaced.  Putting the
    same id with identical state and audit digests is idempotent: a fresh
    dict is returned without touching the file bytes.  The same id with
    different digests raises :class:`ValueError` and leaves the file
    unchanged.  The returned dict always has the key order
    ``audit``, ``id``, ``state``.

    Type violations raise :class:`TypeError`; a bad key set, id or digest
    format raises :class:`ValueError`; a corrupt index raises
    :class:`CorruptReceiptError`; other filesystem errors propagate as
    :class:`OSError`.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    record = _validated_receipt(receipt)

    records = _read_index(path)
    for existing in records:
        if existing[ID] == record[ID]:
            if (
                existing[STATE] != record[STATE]
                or existing[AUDIT] != record[AUDIT]
            ):
                raise ValueError(
                    f"receipt id {record[ID]!r} is already bound to a "
                    "different state or audit record"
                )
            # Idempotent replay: brand-new copy, no filesystem change.
            return dict(record)

    records.append(record)
    records.sort(key=lambda entry: entry[ID])
    _atomic_write(path, _serialize_index(records))
    return dict(record)


def get(path: str, id: str) -> dict[str, str] | None:
    """Return a fresh copy of the receipt stored under ``id``, or None.

    A missing index file or an index without that id yields ``None``.
    Type violations raise :class:`TypeError`; a malformed ``id`` raises
    :class:`ValueError`; a corrupt index raises
    :class:`CorruptReceiptError`; other filesystem errors propagate as
    :class:`OSError`.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    if not isinstance(id, str):
        raise TypeError("id must be a str")
    if _ID_RE.fullmatch(id) is None:
        raise ValueError("id must match [A-Za-z0-9._-]{1,64}")

    for record in _read_index(path):
        if record[ID] == id:
            return dict(record)
    return None

def _serialize_ledger(
    state: dict, requests: dict[str, str], entries: list[dict]
) -> bytes:
    """Canonical ledger bytes: compact JSON, sorted keys, one trailing LF."""
    ledger = {
        AUDIT: [_serialize_entry(entry) for entry in entries],
        REQUESTS: dict(requests),
        STATE_KEY: {
            merge.CLOCK: state[merge.CLOCK],
            merge.RECORDS: state[merge.RECORDS],
        },
        "version": LEDGER_VERSION,
    }
    text = json.dumps(
        ledger, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ) + "\n"
    return text.encode("utf-8")


def _is_digest(value: object) -> bool:
    return isinstance(value, str) and _DIGEST_RE.fullmatch(value) is not None


def _parse_ledger(raw: bytes) -> tuple[dict, dict[str, str], list[dict]]:
    """Validate every byte of a ledger into (state, requests, audit).

    Any decoding, structural, state, index or chain violation raises
    :class:`ValueError`; in particular a type fault in the stored state is
    an on-disk corruption, not a :class:`TypeError`.
    """
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _ledger_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise _ledger_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise _ledger_invalid("must be a JSON object")
    if set(data.keys()) != set(_LEDGER_TOP_KEYS):
        raise _ledger_invalid(
            "must contain exactly the keys 'audit', 'requests', 'state' "
            "and 'version'"
        )
    version = data["version"]
    if isinstance(version, bool) or not isinstance(version, int):
        raise _ledger_invalid("version must be an int")
    if version != LEDGER_VERSION:
        raise _ledger_invalid("version must be the integer 1")

    try:
        clock, records = merge._validated_state(data[STATE_KEY])
    except (TypeError, ValueError) as exc:
        raise _ledger_invalid(f"state is invalid: {exc}") from exc
    state = {merge.CLOCK: clock, merge.RECORDS: records}

    raw_requests = data[REQUESTS]
    if not isinstance(raw_requests, dict):
        raise _ledger_invalid("requests must be a JSON object")
    requests: dict[str, str] = {}
    for bound_id, bound_digest in raw_requests.items():
        if not isinstance(bound_id, str) or bound_id == "":
            raise _ledger_invalid("requests keys must be non-empty str")
        if not _is_digest(bound_digest):
            raise _ledger_invalid(
                "requests values must be 64 lowercase hex characters"
            )
        requests[bound_id] = bound_digest

    raw_entries = data[AUDIT]
    if not isinstance(raw_entries, list):
        raise _ledger_invalid("audit must be an array")
    entries: list[dict] = []
    seen_ids: set[str] = set()
    expected_seq = 1
    expected_before: str | None = None
    for position, entry in enumerate(raw_entries):
        if not isinstance(entry, dict):
            raise _ledger_invalid(f"audit entry {position} must be an object")
        entry_keys = set(entry.keys())
        if entry_keys != _LEDGER_ENTRY_KEY_SET and entry_keys != _LEDGER_ENTRY_AUTHED_SET:
            raise _ledger_invalid(
                f"audit entry {position} must contain exactly the keys "
                "'after', 'before', 'id', 'seq' and 'source' with "
                "optional 'auth'"
            )
        after_digest = entry[AFTER]
        before_digest = entry[BEFORE]
        entry_id = entry[ID]
        seq = entry["seq"]
        entry_source = entry[SOURCE]
        if not _is_digest(after_digest):
            raise _ledger_invalid(
                f"audit entry {position} after must be 64 lowercase hex characters"
            )
        if not _is_digest(before_digest):
            raise _ledger_invalid(
                f"audit entry {position} before must be 64 lowercase hex characters"
            )
        if not isinstance(entry_id, str) or entry_id == "":
            raise _ledger_invalid(f"audit entry {position} id must be a non-empty str")
        if not isinstance(entry_source, str) or entry_source == "":
            raise _ledger_invalid(
                f"audit entry {position} source must be a non-empty str"
            )
        parsed_auth = None
        if AUTH in entry:
            # Entries committed through apply_signed_remote carry the
            # credentials they were verified against; entries written by
            # plain apply_remote have none and stay readable.
            auth = entry[AUTH]
            if not isinstance(auth, dict) or set(auth.keys()) != _LEDGER_AUTH_KEYS:
                raise _ledger_invalid(
                    f"audit entry {position} auth must contain exactly the "
                    "keys 'keyVersion' and 'node'"
                )
            auth_node = auth[NODE]
            auth_version = auth[KEY_VERSION]
            if not isinstance(auth_node, str) or auth_node == "":
                raise _ledger_invalid(
                    f"audit entry {position} auth node must be a non-empty str"
                )
            if (
                isinstance(auth_version, bool)
                or not isinstance(auth_version, int)
                or auth_version <= 0
            ):
                raise _ledger_invalid(
                    f"audit entry {position} auth keyVersion must be a "
                    "positive int"
                )
            parsed_auth = {KEY_VERSION: auth_version, NODE: auth_node}
        if isinstance(seq, bool) or not isinstance(seq, int):
            raise _ledger_invalid(f"audit entry {position} seq must be an int")
        if seq != expected_seq:
            raise _ledger_invalid(
                f"audit entry {position} seq is {seq}, expected {expected_seq}"
            )
        if entry_id in seen_ids:
            raise _ledger_invalid(
                f"audit entry {position} repeats the already applied id {entry_id!r}"
            )
        if entry_id not in requests:
            raise _ledger_invalid(
                f"audit entry {position} id {entry_id!r} is missing from requests"
            )
        if expected_before is not None and before_digest != expected_before:
            raise _ledger_invalid(
                f"audit entry {position} before does not chain to the previous after"
            )
        parsed_entry = {
            AFTER: after_digest,
            BEFORE: before_digest,
            ID: entry_id,
            "seq": seq,
            SOURCE: entry_source,
        }
        if parsed_auth is not None:
            parsed_entry[AUTH] = parsed_auth
        entries.append(parsed_entry)
        seen_ids.add(entry_id)
        expected_seq += 1
        expected_before = after_digest

    if seen_ids != set(requests):
        raise _ledger_invalid("requests and audit must bind the same ids")
    if entries and entries[-1][AFTER] != _digest(_state_bytes(state)):
        raise _ledger_invalid("last audit after must hash the stored state")

    # The bytes must be the single canonical compact encoding with sorted
    # keys and exactly one trailing newline.
    if not raw.endswith(b"\n") or raw.endswith(b"\n\n"):
        raise _ledger_invalid("must end with exactly one newline")
    if _serialize_ledger(state, requests, entries) != raw:
        raise _ledger_invalid("encoding is not the canonical compact form")
    return state, requests, entries


def _read_ledger(
    path: str, base: dict
) -> tuple[dict, dict[str, str], list[dict]]:
    """Load the ledger at ``path``; a missing file stands for ``base``."""
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        clock, records = merge._validated_state(base)
        return {merge.CLOCK: clock, merge.RECORDS: records}, {}, []
    return _parse_ledger(raw)


def _record_decision(
    local_clock: dict,
    local_record: list | None,
    remote_record: list,
) -> tuple[str, dict | None]:
    """Classify one remote record against the current local state."""
    need = merge._remote_need(remote_record, local_clock)
    if need:
        return STATUS_MISSING, need
    if local_record is None:
        return APPLY, None
    if local_record == remote_record:
        return STATUS_DUPLICATE, None
    if merge._dominates(remote_record[2], local_record[2]):
        return APPLY, None
    if merge._dominates(local_record[2], remote_record[2]):
        return STALE, None
    return CONFLICT, None


def _overall_status(decisions: list[str]) -> str:
    """Overall outcome with missing > conflict > stale > applied > duplicate.

    Any ``missing``/``conflict``/``stale`` item dominates; otherwise the
    request applies as soon as at least one item applies (the rest being
    apply or duplicate), and a batch with nothing to do is duplicate.
    """
    for status in (STATUS_MISSING, CONFLICT, STALE):
        if status in decisions:
            return status
    return STATUS_APPLIED if APPLY in decisions else STATUS_DUPLICATE


def _restore_bytes_quietly(path: str, payload: bytes) -> None:
    """Best-effort rewrite of ``payload`` to ``path`` as one replacement.

    Used when the retained predecessor link is already gone and the
    pre-call bytes survive only in memory.  Every error is swallowed so
    the original exception propagates unchanged.
    """
    tmp_path: str | None = None
    try:
        handle, tmp_path = _reserve_tmp_file(path)
        with handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
        tmp_path = None
        storage._fsync_dir(path)
    except OSError:
        pass
    finally:
        if tmp_path is not None:
            _remove_quietly(tmp_path)


def _rollback_ledger_write(
    path: str,
    tmp_path: str | None,
    backup_path: str | None,
    existed: bool,
    stage: str,
    original: bytes | None,
) -> None:
    """Best-effort rollback of a failed :func:`_atomic_write`.

    ``stage`` records how far the transaction got: ``write`` (temporary
    file written), ``link`` (predecessor hard-linked aside), ``intent``
    (the prepared recovery intent published), ``install`` (temporary
    moved into place), ``sync`` (the directory sync after install),
    ``confirm`` (the installed intent published), ``cleanup`` (the
    predecessor link removed) or ``final`` (the intent removed, its
    directory sync failed).  The predecessor is retained as a hard link
    rather than rewritten, so renaming it back restores the original
    file byte-for-byte (indeed as the same inode) even with no working
    fsync or free space left; once that link is already gone, the
    captured pre-call bytes are rewritten from memory instead.  The
    recovery intent at ``path + ".txn"`` only ever belongs to the failed
    call and is removed as well.  The directory is synced last so the
    recovery is durable.  Every recovery error is swallowed so the
    original exception propagates unchanged.
    """
    try:
        if stage in ("cleanup", "final"):
            # The new ledger was installed and the install synced; only
            # the backup removal, the intent removal or a directory sync
            # failed.  The commit still must not stand: rename the
            # retained link back when it survives, otherwise rewrite the
            # captured pre-call bytes from memory.
            _remove_quietly(tmp_path)
            if backup_path is not None and os.path.exists(backup_path):
                os.replace(backup_path, path)
            elif original is not None:
                _restore_bytes_quietly(path, original)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass
        elif stage in ("sync", "confirm"):
            _remove_quietly(tmp_path)
            if existed:
                os.replace(backup_path, path)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass
        elif stage in ("install", "intent"):
            # The replacement did not run: the predecessor at path is
            # untouched; the backup link and temporary file are internal
            # artifacts to remove.
            if backup_path is not None:
                try:
                    os.unlink(backup_path)
                except FileNotFoundError:
                    pass
            if tmp_path is not None:
                try:
                    os.unlink(tmp_path)
                except FileNotFoundError:
                    pass
        else:
            # write/link stages leave the predecessor in place; the link
            # stage additionally leaves a backup link to remove.
            if tmp_path is not None:
                try:
                    os.unlink(tmp_path)
                except FileNotFoundError:
                    pass
            if stage == "link" and backup_path is not None:
                try:
                    os.unlink(backup_path)
                except FileNotFoundError:
                    pass
        # The recovery intent only ever belongs to this transaction.
        _remove_quietly(path + ".txn")
        try:
            storage._fsync_dir(path)
        except OSError:
            pass
    except OSError:
        pass


def _remove_quietly(target: str) -> None:

RECOVERY_VERSION = 1

PHASE_PREPARED = "prepared"
PHASE_INSTALLED = "installed"

STATUS_CLEAN = "clean"
STATUS_ROLLED_BACK = "rolled-back"
STATUS_COMPLETED = "completed"

INTENT_CANDIDATE = "candidate"
INTENT_NEW_DIGEST = "newDigest"
INTENT_OLD_DIGEST = "oldDigest"
INTENT_PHASE = "phase"
INTENT_PREDECESSOR = "predecessor"

_INTENT_KEYS = frozenset((
    INTENT_CANDIDATE,
    INTENT_NEW_DIGEST,
    INTENT_OLD_DIGEST,
    INTENT_PHASE,
    INTENT_PREDECESSOR,
    VERSION,
))


class CorruptRecoveryError(ValueError):
    """A recovery intent or one of its referenced artifacts is corrupt."""


def _recovery_invalid(message: str) -> CorruptRecoveryError:
    return CorruptRecoveryError(f"invalid recovery intent: {message}")


def _intent_compact(obj: object) -> bytes:
    """Canonical compact sorted-key UTF-8 JSON of intent content."""
    return json.dumps(
        obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")


def _intent_payload(
    phase: str,
    new_digest: str,
    old_digest: str | None,
    candidate_name: str,
    predecessor_name: str | None,
) -> bytes:
    """Canonical intent bytes: compact JSON, sorted keys, one trailing LF."""
    intent = {
        INTENT_CANDIDATE: candidate_name,
        INTENT_NEW_DIGEST: new_digest,
        INTENT_OLD_DIGEST: old_digest,
        INTENT_PHASE: phase,
        INTENT_PREDECESSOR: predecessor_name,
        VERSION: RECOVERY_VERSION,
    }
    return _intent_compact(intent) + b"\n"


def _publish_intent(path: str, payload: bytes) -> None:
    """Atomically publish the recovery intent at ``path + ".txn"``.

    The intent is written to a uniquely named temporary in the same
    directory, flushed and synced, then renamed into place and the
    directory synced, so a crash leaves either no intent or the complete
    intent; the intent's own creation and phase change are as durable as
    the transaction steps they record.
    """
    handle, tmp_path = _reserve_unique_file(f"{path}.txn.")
    try:
        with handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path + ".txn")
        tmp_path = None
    finally:
        if tmp_path is not None:
            _remove_quietly(tmp_path)
    storage._fsync_dir(path)


def _validated_artifact_name(name: object, key: str, ledger_base: str) -> None:
    """Require a safe base name confined to the ledger's own directory."""
    if not isinstance(name, str) or name == "":
        raise _recovery_invalid(f"{key} must be a non-empty str")
    if (
        name in (".", "..")
        or os.path.basename(name) != name
        or os.sep in name
        or (os.altsep is not None and os.altsep in name)
    ):
        raise _recovery_invalid(f"{key} must be a plain base name")
    if name == ledger_base or name == ledger_base + ".txn":
        raise _recovery_invalid(
            f"{key} must not name the ledger or the intent itself"
        )


def _parse_intent(raw: bytes, ledger_base: str) -> dict:
    """Validate every byte of a recovery intent and return its decoded form.

    Any decoding, structural, phase, name or digest violation raises
    :class:`CorruptRecoveryError`.
    """
    if not raw.endswith(b"\n") or raw.endswith(b"\n\n"):
        raise _recovery_invalid("must be a single JSON object ending in one LF")
    try:
        text = raw[:-1].decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _recovery_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise _recovery_invalid("is not valid JSON") from exc

    if not isinstance(data, dict) or set(data.keys()) != _INTENT_KEYS:
        raise _recovery_invalid(
            "must contain exactly the keys 'candidate', 'newDigest', "
            "'oldDigest', 'phase', 'predecessor' and 'version'"
        )
    version = data[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise _recovery_invalid("version must be an int")
    if version != RECOVERY_VERSION:
        raise _recovery_invalid("version must be the integer 1")
    phase = data[INTENT_PHASE]
    if phase not in (PHASE_PREPARED, PHASE_INSTALLED):
        raise _recovery_invalid("phase must be 'prepared' or 'installed'")
    if not _is_digest(data[INTENT_NEW_DIGEST]):
        raise _recovery_invalid("newDigest must be 64 lowercase hex characters")
    old_digest = data[INTENT_OLD_DIGEST]
    if old_digest is not None and not _is_digest(old_digest):
        raise _recovery_invalid(
            "oldDigest must be null or 64 lowercase hex characters"
        )
    _validated_artifact_name(data[INTENT_CANDIDATE], "candidate", ledger_base)
    predecessor = data[INTENT_PREDECESSOR]
    if predecessor is not None:
        _validated_artifact_name(predecessor, "predecessor", ledger_base)
    if (old_digest is None) != (predecessor is None):
        raise _recovery_invalid(
            "oldDigest and predecessor must both be null or both be set"
        )

    # The bytes must be the single canonical compact encoding with
    # recursively sorted keys and exactly one trailing newline.
    if _intent_compact(data) + b"\n" != raw:
        raise _recovery_invalid("encoding is not the canonical compact form")
    return data


def recover_ledger(path: str) -> dict:
    """Reconcile an interrupted ledger transaction at ``path``.

    When no recovery intent exists at ``path + ".txn"`` the result is
    ``clean`` and no random artifacts are scanned.  Otherwise the intent
    is fully validated -- a parse, field, phase, name, digest or
    necessary-artifact violation raises :class:`CorruptRecoveryError` (a
    :class:`ValueError`) without touching the ledger or any unrelated
    file -- and the interrupted transaction is settled by its phase:

    - ``prepared``: the commit was never confirmed.  The old bytes are
      kept or restored byte-for-byte from the retained predecessor (the
      path stays missing when it was missing) and the referenced new
      candidate is deleted; the status is ``rolled-back``.
    - ``installed``: the new ledger already replaced the old one and the
      directory synced.  The current bytes must hash to ``newDigest``;
      the remaining referenced artifacts are cleaned and the status is
      ``completed``.

    Only files the intent references are removed, the intent itself is
    deleted last and the directory is synced, so a repeated call reports
    ``clean``.  The result is a fresh dict with the key order ``digest``,
    ``status``; ``digest`` is the digest of the resulting ledger bytes,
    or ``None`` when the path is missing.  A ``path`` that is not a str
    raises :class:`TypeError`; an :class:`OSError` while reading,
    replacing, deleting or syncing propagates unchanged with enough
    intent and artifacts left in place for a retry.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    try:
        with open(path + ".txn", "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        # No intent: nothing to settle, and random leftover artifacts
        # are never scanned.  The digest still summarizes the ledger
        # bytes currently at the path (None when the path is missing).
        try:
            with open(path, "rb") as handle:
                current = handle.read()
        except FileNotFoundError:
            current = None
        return {
            "digest": _digest(current) if current is not None else None,
            STATUS: STATUS_CLEAN,
        }

    ledger_base = os.path.basename(path)
    intent = _parse_intent(raw, ledger_base)
    phase = intent[INTENT_PHASE]
    new_digest = intent[INTENT_NEW_DIGEST]
    old_digest = intent[INTENT_OLD_DIGEST]
    directory = os.path.dirname(os.path.abspath(path))
    candidate_path = os.path.join(directory, intent[INTENT_CANDIDATE])
    predecessor_path = (
        os.path.join(directory, intent[INTENT_PREDECESSOR])
        if intent[INTENT_PREDECESSOR] is not None
        else None
    )

    try:
        with open(path, "rb") as handle:
            current = handle.read()
    except FileNotFoundError:
        current = None

    # Every validation finishes before the first mutation, so a
    # CorruptRecoveryError never changes the ledger or any other file.
